import sqlite3
from dataclasses import dataclass

from agents import function_tool as tool


@dataclass
class PauseResult:
    subscription_id: str
    paused: bool
    resume_on: str


@tool
def pause_subscription(subscription_id: str, resume_on: str) -> PauseResult:
    conn = sqlite3.connect("subscriptions.db")
    with conn:
        cur = conn.execute(
            "UPDATE subscriptions SET status = 'paused', resume_on = ? "
            "WHERE id = ? AND status = 'active'",
            (resume_on, subscription_id),
        )
    conn.close()
    return PauseResult(subscription_id, cur.rowcount == 1, resume_on)
